<?php
// The library remains useful before the community has published content.
$feedLanguage=networkFeedLanguage();$country=is_string($_GET['country']??null)?$_GET['country']:'';
if($city!==''&&isset(tripDestinations()[$city]))$country=tripDestinations()[$city]['country'];
$homeFeed=!$owner&&$tab!=='saved';if($homeFeed)$title=scText('Feed','פיד','Лента');
$feedUrl=fn(array $changes=[])=>languageUrl('/community/?'.http_build_query(array_replace(['feed_language'=>$feedLanguage,'tab'=>$tab,'type'=>$type,'country'=>$country,'city'=>$city,'q'=>$search,'budget'=>$budget,'minutes'=>$minutes],$changes)),siteLanguage());
if($homeFeed): ?><section class="sc-feed-controls"><div class="sc-feed-heading"><h1><?=e(scText('Feed','פיד','Лента'))?></h1><p><?=e(scText('A community for travel stories, places and plans.','קהילה לחוויות מהטיול, מקומות ותוכניות.','Сообщество историй, мест и планов путешествий.'))?></p></div><nav class="network-tabs"><a href="<?=e($feedUrl(['tab'=>'for_you']))?>" <?=$tab==='for_you'?'aria-current="page"':''?>><?=$n('for_you')?></a><a href="<?=e($feedUrl(['tab'=>'following']))?>" <?=$tab==='following'?'aria-current="page"':''?>><?=$n('following')?></a></nav><?php endif?>
<form method="post" class="network-feed-language"><?=csrf()?><input type="hidden" name="network_action" value="feed_language"><label><span><span aria-hidden="true">🔤</span> <?=e(nt('feed_language'))?></span><select name="feed_language"><?=networkLanguageOptions($feedLanguage,true)?></select></label><?php networkDestinationPicker($country,$city,$feedUrl());?><button class="sc-filter-fallback"><?=e(nt('apply_language'))?></button></form>
<form class="network-filter network-home-filter" method="get"><label class="network-search-label"><span class="sr-only"><?=$n('search')?></span><input name="q" placeholder="<?=$n('search')?>" maxlength="100" value="<?=e($search)?>"></label><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><input type="hidden" name="feed_language" value="<?=e($feedLanguage)?>"><input type="hidden" name="country" value="<?=e($country)?>"><input type="hidden" name="tab" value="<?=e($tab)?>"><details class="network-filter-details"><summary><?=$n('filters')?></summary><div><label><?=$n('post')?><select name="type"><?php foreach(publicationFilterLabels() as $v=>$label):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><input type="hidden" name="city" value="<?=e($city)?>"><label><?=$n('cost')?><select name="budget"><option value=""><?=$n('all')?></option><?php foreach(['free','paid'] as $cost):?><option value="<?=$cost?>" <?=$budget===$cost?'selected':''?>><?=$n($cost)?></option><?php endforeach?></select></label><label><?=$n('minutes')?><input type="number" name="minutes" min="0" max="1440" value="<?=$minutes?>"></label></div></details><button><?=$n('filter')?></button></form>
<?php if($homeFeed):?></section><section class="network-composer network-card"><a href="<?=$nu('/community/create/')?>"><?=networkAvatar($me?:['name'=>'','handle'=>'T'])?><span><?=e(scText('Share a travel experience or ask a question…','שתפו חוויה מהטיול או שאלו שאלה…','Поделитесь впечатлением или задайте вопрос…'))?></span></a><?php networkCreationChoices();?></section><?php endif?>
<?php if($type||$search||$budget||$minutes):?><p class="network-filter-summary"><?=e(implode(' · ',array_filter([$type?nt($type):'',(!$city&&$country)?activityLabel((tripDestinations()[networkCountryCities($country)[0]??'']['country_labels']??['','','',''])):'',activityLabel(tripDestinations()[$city]['labels']??['','','','']),$search,$budget?nt($budget):'',$minutes?$minutes.' '.nt('minutes'):''])))?> <a href="<?=e(languageUrl($path.'?tab='.$tab.'&feed_language='.rawurlencode($feedLanguage),siteLanguage()))?>"><?=$n('clear_filters')?></a></p><?php endif?>
<?php 
if($tab==='saved'&&!$u){echo '<section class="network-card"><h2>'.e(nt('saved')).'</h2><div data-guest-saved></div></section>';}
$savedPlaces=[];if($tab==='saved'&&$u){foreach(socialQuery("SELECT target FROM network_edges WHERE actor=? AND kind='save' AND target LIKE 'catalog:%' ORDER BY created DESC",[$u['id']]) as $saved){$pid=substr($saved['target'],8);if(isset(scCatalogue()[$pid]))$savedPlaces[]=scCatalogue()[$pid];}if($savedPlaces){echo '<section class="network-card"><h2>'.e(scText('Saved places','מקומות שמורים','Сохранённые места')).'</h2>';foreach($savedPlaces as $place)scPlaceTile($place,true);echo '</section>';}}
$feed=networkFeed(['language'=>$feedLanguage,'country'=>$country,'city'=>$city,'tab'=>$tab,'owner'=>$owner,'type'=>$type,'q'=>$search,'budget'=>$budget,'minutes'=>$minutes,'cursor'=>is_string($_GET['cursor']??null)?$_GET['cursor']:'']);

$library='';if(!$feed['rows']&&in_array($feedLanguage,['all',siteLanguage()],true)&&!$owner&&$tab==='for_you'&&in_array($type,['','place'],true)&&empty($_GET['cursor'])){ob_start();networkCatalogueCards($city,array_column(array_filter($feed['rows'],fn($r)=>$r['kind']==='place'),'target'),$country);$library=ob_get_clean();}
if(!$feed['rows']&&!$library&&!$savedPlaces&& !($tab==='saved'&&!$u)):?><section class="network-empty network-card"><h2><?=e($ownPending?networkAuditLabel('no_public'):nt($tab==='following'?'following_empty':'no_posts'))?></h2><p><?=$n($tab==='following'?'following_help':'empty_help')?></p><a class="button" href="<?=e($feedUrl(['tab'=>'for_you','type'=>'','country'=>'','city'=>'','q'=>'','budget'=>'','minutes'=>0]))?>"><?=$n('for_you')?></a><a href="<?=$nu('/explore/')?>"><?=$n('places_library')?></a></section><?php networkEvent('empty_feed','feed',$city,siteLanguage().':'.$city.':'.gmdate('Y-m-d-H'));endif;
echo '<div data-feed-pages>';foreach($feed['rows'] as $row)networkCard($row);echo '</div>';
echo $library;
if(!$feed['rows']&&!$library&&$homeFeed){
 require_once ROOT.'/src/explore.php';$suggestions=array_slice(exFilter(exCatalogue(),['city'=>$city,'country'=>$country,'cost'=>$budget,'tab'=>'places','q'=>$search,'minutes'=>$minutes]),0,3);
 echo '<section class="network-card"><h2>'.e(nt('places_library')).'</h2><p>'.e(nt('original_only')).'</p>';
 foreach($suggestions as $place){scPlaceTile($place,true);parse_str(parse_url($place['url']??'',PHP_URL_QUERY)??'',$edition);echo networkLanguageBadge($edition['content_lang']??siteLanguage());}
 echo '<a class="button secondary" href="'.e(languageUrl('/explore/?'.http_build_query(['country'=>$country,'destination'=>$city,'cost'=>$budget]),siteLanguage())).'">'.e(nt('places_library')).'</a> <a href="'.e(languageUrl('/community/create/?kind=question&'.http_build_query(['city'=>$city,'country'=>$country]),siteLanguage())).'">'.e(nt('question')).'</a></section>';
}
if($feed['next']):?><a data-feed-next class="button secondary" href="<?=e(languageUrl($path.'?'.http_build_query(['feed_language'=>$feedLanguage,'country'=>$country,'city'=>$city,'tab'=>$tab,'type'=>$type,'q'=>$search,'budget'=>$budget,'minutes'=>$minutes,'cursor'=>$feed['next']]),siteLanguage()))?>"><?=$n('next')?></a><?php elseif($library):?><a class="button secondary" href="<?=e(languageUrl('/explore/?'.http_build_query(['country'=>$country,'destination'=>$city,'q'=>$search,'cost'=>$budget]),siteLanguage()))?>"><?=$n('library_more')?></a><?php endif?>

